import { eq, desc, and, or, count as drizzleCount } from 'drizzle-orm'
import { blogAuthors, blogPosts } from '@growth-engine/types/schema'
import type { BlogPost, BlogAuthor } from '@growth-engine/types'
import type { getClientDb } from '../handler/db'

export type ClientDb = ReturnType<typeof getClientDb>

const DEFAULT_LIMIT = 20
const MAX_LIMIT = 5000

function resolveLimit(limit?: number): number {
  if (limit === undefined) return DEFAULT_LIMIT
  if (limit <= 0) return MAX_LIMIT
  return Math.min(limit, MAX_LIMIT)
}

export interface GetBlogPostsOptions {
  locale?: string | undefined
  limit?: number | undefined
  offset?: number | undefined
}

export async function getBlogPosts(
  db: ClientDb,
  opts?: GetBlogPostsOptions,
): Promise<BlogPost[]> {
  const locale = opts?.locale ?? 'en'
  const limit = resolveLimit(opts?.limit)
  const offset = opts?.offset ?? 0

  const rows = await db
    .select()
    .from(blogPosts)
    .where(and(
      eq(blogPosts.status, 'published'),
      eq(blogPosts.language, locale),
    ))
    .orderBy(desc(blogPosts.createdAt))
    .limit(limit)
    .offset(offset)

  return rows as BlogPost[]
}

export async function getBlogPost(
  db: ClientDb,
  slug: string,
  locale?: string | undefined,
): Promise<BlogPost | null> {
  const slugMatch = or(eq(blogPosts.slug, slug), eq(blogPosts.urlPath, slug))
  const conditions = [slugMatch!]
  if (locale) conditions.push(eq(blogPosts.language, locale))

  const rows = await db
    .select()
    .from(blogPosts)
    .where(and(...conditions))
    .limit(1)

  return (rows[0] as BlogPost) ?? null
}

export async function getBlogPostCount(
  db: ClientDb,
  locale?: string | undefined,
): Promise<number> {
  const conditions = [eq(blogPosts.status, 'published')]
  if (locale) conditions.push(eq(blogPosts.language, locale))

  const result = await db
    .select({ count: drizzleCount() })
    .from(blogPosts)
    .where(and(...conditions))

  return result[0]?.count ?? 0
}

export async function getBlogAuthors(
  db: ClientDb,
): Promise<BlogAuthor[]> {
  const rows = await db
    .select()
    .from(blogAuthors)
    .orderBy(desc(blogAuthors.createdAt))

  return rows as BlogAuthor[]
}

export async function getBlogAuthor(
  db: ClientDb,
  slug: string,
): Promise<BlogAuthor | null> {
  const rows = await db
    .select()
    .from(blogAuthors)
    .where(eq(blogAuthors.slug, slug))
    .limit(1)

  return (rows[0] as BlogAuthor) ?? null
}

export async function getBlogAuthorById(
  db: ClientDb,
  id: string,
): Promise<BlogAuthor | null> {
  const rows = await db
    .select()
    .from(blogAuthors)
    .where(eq(blogAuthors.id, id))
    .limit(1)

  return (rows[0] as BlogAuthor) ?? null
}

export async function getAuthorPosts(
  db: ClientDb,
  authorSlug: string,
  opts?: { locale?: string | undefined, limit?: number | undefined, offset?: number | undefined },
): Promise<BlogPost[]> {
  const author = await db
    .select()
    .from(blogAuthors)
    .where(eq(blogAuthors.slug, authorSlug))
    .limit(1)

  if (!author[0]) return []

  const locale = opts?.locale ?? 'en'
  const limit = resolveLimit(opts?.limit)
  const offset = opts?.offset ?? 0

  const rows = await db
    .select()
    .from(blogPosts)
    .where(and(
      eq(blogPosts.status, 'published'),
      eq(blogPosts.language, locale),
      eq(blogPosts.authorId, author[0].id),
    ))
    .orderBy(desc(blogPosts.createdAt))
    .limit(limit)
    .offset(offset)

  return rows as BlogPost[]
}
