// ─── Nurture Flows ─────────────────────────────────────────────────────
export const nurtureFlows = sqliteTable('nurture_flows', {
	id: text('id').primaryKey(),
	name: text('name').notNull(),
	description: text('description'),
	// JSON NurtureTrigger[] (array). Legacy rows may contain a single object —
	// parseFlow normalizes both shapes to an array.
	trigger: text('trigger').notNull().default('[]'),
	nodes: text('nodes').notNull().default('[]'), // JSON NurtureNode[]
	edges: text('edges').notNull().default('[]'), // JSON NurtureEdge[]
	stopConditions: text('stop_conditions').notNull().default('[]'), // JSON NurtureStopCondition[]
	onStop: text('on_stop').notNull().default('{}'), // JSON { promoteToChecklistId?: string }
	senderRef: text('sender_ref'), // JSON SenderRef — who sends this flow's emails (null → tenant default)
	status: text('status', { enum: ['active', 'archived'] }).notNull().default('active'),
	createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
	updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull(),
})

// ─── Nurture API Tokens ────────────────────────────────────────────────
// Per-flow API tokens for Zapier / external triggering of the manual trigger.
// Only the SHA-256 hash is stored. Raw token returned ONCE at creation.
export const nurtureApiTokens = sqliteTable('nurture_api_tokens', {
	id: text('id').primaryKey(),
	flowId: text('flow_id').notNull(),
	name: text('name').notNull(),
	tokenHash: text('token_hash').notNull(),
	prefix: text('prefix').notNull(), // First 12 chars of raw token, for display
	createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
	lastUsedAt: integer('last_used_at', { mode: 'timestamp' }),
	revokedAt: integer('revoked_at', { mode: 'timestamp' }),
})

// ─── Nurture Runs ──────────────────────────────────────────────────────
export const nurtureRuns = sqliteTable('nurture_runs', {
	id: text('id').primaryKey(),
	flowId: text('flow_id').notNull(),
	contactId: text('contact_id').notNull(),
	contactName: text('contact_name').notNull(),
	contactEmail: text('contact_email'),
	contactCompany: text('contact_company'),
	currentNodeId: text('current_node_id'),
	nodeState: text('node_state').notNull().default('{}'), // JSON Record<nodeId, NurtureNodeState>
	// Run-scoped key→value blob populated by `workflow` nodes (outputKey → workflow output).
	// Referenced by downstream emails via {{workflow.<outputKey>.<field>}} merge expressions
	// and surfaced to personalizeEmailWithAi as structured context.
	runContext: text('run_context').notNull().default('{}'),
	status: text('status', { enum: ['active', 'stopped', 'completed'] }).notNull().default('active'),
	stopReason: text('stop_reason'),
	createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
	updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull(),
})

