export const expertChatMessages = sqliteTable('expert_chat_messages', {
  id: text('id').primaryKey(),
  sessionId: text('session_id')
    .notNull()
    .references(() => expertChatSessions.id, { onDelete: 'cascade' }),
  role: text('role', { enum: ['user', 'assistant', 'tool', 'system'] }).notNull(),
  content: text('content', { mode: 'json' }).notNull(),
  tokensIn: integer('tokens_in').notNull().default(0),
  tokensOut: integer('tokens_out').notNull().default(0),
  costCents: integer('cost_cents').notNull().default(0),
  errorMessage: text('error_message'),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
})

// ─── KB Gaps ─────────────────────────────────────────────────────────────────

export const kbGaps = sqliteTable('kb_gaps', {
  id: text('id').primaryKey(),
  expertId: text('expert_id')
    .notNull()
    .references(() => experts.id, { onDelete: 'cascade' }),
  sessionId: text('session_id').references(() => expertChatSessions.id, { onDelete: 'set null' }),
  messageId: text('message_id'),
  question: text('question').notNull(),
  source: text('source', { enum: ['auto', 'user_reported'] }).notNull(),
  status: text('status', { enum: ['open', 'answered', 'dismissed'] })
    .notNull()
    .default('open'),
  resolvedEntryId: text('resolved_entry_id').references(() => kbEntries.id, {
    onDelete: 'set null',
  }),
  resolvedBy: text('resolved_by'),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  resolvedAt: integer('resolved_at', { mode: 'timestamp' }),
})

// ─── Operator (portal agent harness) ────────────────────────────────────────

export const operatorSessions = sqliteTable('operator_sessions', {
  id: text('id').primaryKey(),
  title: text('title'),
  startedBy: text('started_by').notNull(), // lowercased user email
  startedAt: integer('started_at', { mode: 'timestamp' }).notNull(),
  lastMessageAt: integer('last_message_at', { mode: 'timestamp' }).notNull(),
  messageCount: integer('message_count').notNull().default(0),
})

export const operatorMessages = sqliteTable('operator_messages', {
  id: text('id').primaryKey(),
  sessionId: text('session_id')
    .notNull()
    .references(() => operatorSessions.id, { onDelete: 'cascade' }),
  role: text('role', { enum: ['user', 'assistant', 'tool'] }).notNull(),
  content: text('content', { mode: 'json' }).notNull(),
  tokensIn: integer('tokens_in').notNull().default(0),
  tokensOut: integer('tokens_out').notNull().default(0),
  costCents: integer('cost_cents').notNull().default(0),
  errorMessage: text('error_message'),
  confirmedAt: integer('confirmed_at', { mode: 'timestamp' }),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
})

export const operatorPermissions = sqliteTable('operator_permissions', {
  id: text('id').primaryKey(),
  userEmail: text('user_email').notNull().unique(), // lowercased; unique per tenant DB
  enabled: integer('enabled', { mode: 'boolean' }).notNull().default(false),
  // Record<DomainKey, 'none' | 'read' | 'write' | 'destructive'>
  domains: text('domains', { mode: 'json' })
    .$type<Record<string, 'none' | 'read' | 'write' | 'destructive'>>()
    .notNull(),
  // Record<toolName, 'allow' | 'deny'>
  toolOverrides: text('tool_overrides', { mode: 'json' })
    .$type<Record<string, 'allow' | 'deny'>>()
    .notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull(),
  updatedBy: text('updated_by'),
})

// ─── Operator channel gateway (external channels → Operator) ────────────────
// One thread per provider conversation (Slack thread, Telegram chat, email
// subject chain). Each thread is backed by a normal operator_sessions row so
// channel conversations share history/persistence with the portal Operator.

export const operatorChannelThreads = sqliteTable(
  'operator_channel_threads',
  {
    id: text('id').primaryKey(),
    provider: text('provider').notNull(),
    bindingId: text('binding_id').notNull(),
    integrationInstanceId: text('integration_instance_id').notNull(),
    externalThreadId: text('external_thread_id').notNull(),
    externalConversationId: text('external_conversation_id'),
    operatorSessionId: text('operator_session_id')
      .notNull()
      .references(() => operatorSessions.id, { onDelete: 'cascade' }),
    startedByExternalUserId: text('started_by_external_user_id'),
    lastMessageAt: integer('last_message_at', { mode: 'timestamp' }).notNull(),
    createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  },
  (t) => [uniqueIndex('operator_channel_threads_provider_binding_thread_unique').on(t.provider, t.bindingId, t.externalThreadId)],
)

export const operatorChannelMessages = sqliteTable('operator_channel_messages', {
  id: text('id').primaryKey(),
  threadId: text('thread_id')
    .notNull()
    .references(() => operatorChannelThreads.id, { onDelete: 'cascade' }),
  direction: text('direction', { enum: ['inbound', 'outbound'] }).notNull(),
  providerMessageId: text('provider_message_id'),
  operatorMessageId: text('operator_message_id').references(() => operatorMessages.id, {
    onDelete: 'set null',
  }),
  externalUserId: text('external_user_id'),
  externalUserLabel: text('external_user_label'),
  text: text('text').notNull(),
  status: text('status', {
    enum: ['received', 'ignored', 'queued', 'sent', 'drafted', 'failed'],
  }).notNull(),
  reason: text('reason'),
  rawSummary: text('raw_summary', { mode: 'json' }).$type<Record<string, unknown>>(),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
})

export type OperatorSession = typeof operatorSessions.$inferSelect
export type OperatorMessage = typeof operatorMessages.$inferSelect
export type OperatorPermission = typeof operatorPermissions.$inferSelect
export type OperatorChannelThread = typeof operatorChannelThreads.$inferSelect
export type OperatorChannelMessage = typeof operatorChannelMessages.$inferSelect
